protected static List<Object[]> fetchTestParams(String baseDir, ExecuteWith executeWith) throws IOException {
  String[] modelNames = modelDirNames(baseDir, executeWith);
  List<Object[]> modelParams = new ArrayList<>();
  for (int i = 0; i < modelNames.length; i++) {
    Object[] currentParams = new Object[3];
    currentParams[0] = inputVars(modelNames[i], baseDir);
    try {
      currentParams[1] = outputVars(modelNames[i], baseDir);
    } catch (IllegalArgumentException | ArrayIndexOutOfBoundsException | NullPointerException | IndexOutOfBoundsException e) {
      // Handle the exception, for example, by logging or setting a default value
      currentParams[1] = null; // or some other default handling
    }
    currentParams[2] = modelNames[i];
    modelParams.add(currentParams);
  }
  return modelParams;
}
